/**
 * Brand typefaces for the jsPDF download path.
 *
 * The printed HTML documents carry Archivo and Bricolage Grotesque through
 * @font-face; jsPDF draws with its own built-in Helvetica unless
 * a TTF is registered, so every downloaded PDF used to leave the brand behind.
 * These are static instances cut from the same variable woff2 files the panel
 * ships (fontTools instancer: Archivo wght 400/700, Bricolage wght 800 opsz 24),
 * base64-encoded because jsPDF's virtual file system
 * takes a string.
 *
 * Registration goes through jsPDF's own `addFonts` event so every document
 * created from the class gets the faces without each builder remembering to.
 * Generated by tools — do not hand-edit the data strings.
 */

export const PDF_FONT_FACES = [
  { file: "Archivo-Regular.ttf", family: "Archivo", style: "normal", data:
"" },
  { file: "Archivo-Bold.ttf", family: "Archivo", style: "bold", data:
"" },
  { file: "BricolageGrotesque-ExtraBold.ttf", family: "BricolageGrotesque", style: "bold", data:
"" },
];

/** Font family names as registered with jsPDF. */
export const PDF_FACE = Object.freeze({
  body: "Archivo",
  display: "BricolageGrotesque",
});

let registered = false;

/**
 * Install the faces on a jsPDF class (not an instance) exactly once. Safe to
 * call repeatedly; safe when jsPDF is absent (returns false).
 */
export function registerPdfFonts(JsPDF) {
  if (registered || !JsPDF?.API?.events?.push) return registered;
  JsPDF.API.events.push([
    "addFonts",
    function addBrandFonts() {
      for (const face of PDF_FONT_FACES) {
        this.addFileToVFS(face.file, face.data);
        this.addFont(face.file, face.family, face.style);
      }
    },
  ]);
  registered = true;
  return true;
}
